# Plan 02: Aufbau und Ermüdung auf den echten Daten, über den Produktionsweg (Annotationen angewendet)
suppressPackageStartupMessages({library(here);library(dplyr);library(readr);library(tibble)})
source(here("scripts","helpers.R")); source(here("scripts","load_recovery.R"))
d <- read_csv(here("data","garmin_daily.csv"),show_col_types=FALSE) |> apply_annotations(read_annotations())
a <- read_csv(here("data","garmin_activities.csv"),show_col_types=FALSE,col_types=cols(activity_id=col_character(),start=col_datetime(),name=col_character(),type_key=col_character(),.default=col_double()))
am <- merge_rides(a,30,3); zn <- read_csv(here("data","garmin_activity_zones.csv"),show_col_types=FALSE,col_types=cols(activity_id=col_character(),.default=col_double()))
p <- athlete_profile(median(d$resting_hr[d$resting_hr>=45],na.rm=T))
dl <- daily_load_recovery(d, session_load(am,p,0.4,zn))
cat("Tage:", nrow(dl), " davon eingefroren (pmc_gap):", sum(dl$pmc_gap), " Einschwingphase:", sum(dl$pmc_warmup), "\n")
cat("Letzter Tag:", format(max(dl$date)), " CTL", round(tail(dl$ctl,1),1), " ATL", round(tail(dl$atl,1),1), " Form", round(tail(dl$tsb,1),1), "\n")
cat("Spanne CTL:", round(range(dl$ctl),1), " ATL:", round(range(dl$atl),1), "\n")
cat("\nSensitivität: Behandlung unbekannter Tage\n"); print(pmc_sensitivity(dl$load, !dl$unrecorded & !dl$partial), digits = 3)
cat("\nBeispiel Segeltörn (Zustand eingefroren):\n")
s <- dl |> filter(date >= as.Date("2026-07-29"), date <= as.Date("2026-08-02")) |> select(date, load, ctl, atl, pmc_gap); print(s)
